body.script:
    const { boundary, districts, mahallas } = window.APP_DATA;
    const info = document.getElementById('info');
    const districtSelect = document.getElementById('districtSelect');
    const searchInput = document.getElementById('searchInput');
    const districtCount = document.getElementById('districtCount');
    const mahallaCount = document.getElementById('mahallaCount');
    const resetBtn = document.getElementById('resetBtn');
    const satBtn = document.getElementById('satBtn');

    districtCount.textContent = `Tumanlar: ${districts.features.length}`;
    mahallaCount.textContent = `MFYlar: ${mahallas.features.length}`;

    const map = L.map('map', { zoomControl: true, preferCanvas: true });

    const streets = L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
      attribution: '© OpenStreetMap'
    });

    const satellite = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', {
      maxZoom: 19,
      attribution: 'Tiles © Esri'
    });

    const light = L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png', {
      subdomains: 'abcd',
      maxZoom: 20,
      attribution: '© OpenStreetMap © CARTO'
    }).addTo(map);

    const baseLayers = {
      'Oddiy xarita': streets,
      'Yengil xarita': light,
      'Sun’iy yo‘ldosh': satellite,
    };

    L.control.layers(baseLayers, null, { collapsed: true }).addTo(map);

    function setInfo(html) {
      info.innerHTML = `Ma’lumot
${html}`;
    }

    const districtStyle = {
      color: '#2563eb',
      weight: 2,
      fillColor: '#60a5fa',
      fillOpacity: 0.16
    };

    function districtFeatureStyle(feature) {
      return districtStyle;
    }

    function mahallaFeatureStyle(feature) {
      return {
        color: '#16a34a',
        weight: 1,
        fillColor: '#4ade80',
        fillOpacity: 0.18
      };
    }

    const boundaryLayer = L.geoJSON(boundary, {
      style: { color:'#0f172a', weight: 3, fill:false, opacity:0.9 }
    }).addTo(map);

    let currentDistrict = '';
    let filteredMahallas = null;
    let selectedMahallaLayer = null;

    const districtLayer = L.geoJSON(districts, {
      style: districtFeatureStyle,
      onEachFeature: (feature, layer) => {
        const name = feature.properties.district;
        layer.bindPopup(`${name}`);
        layer.on({
          click: () => focusDistrict(name),
          mouseover: () => layer.setStyle({ fillOpacity: 0.28, weight: 3 }),
          mouseout: () => {
            if (currentDistrict !== name) districtLayer.resetStyle(layer);
          }
        });
      }
    }).addTo(map);

    const allMahallaLayer = L.geoJSON(mahallas, {
      style: mahallaFeatureStyle,
      onEachFeature: (feature, layer) => {
        const p = feature.properties;
        layer.bindPopup(`${p.mahalla_no}
Tuman: ${p.district}
ID: ${p.mahalla_id}`);
        layer.on('click', () => focusMahallaLayer(layer, feature));
      }
    }).addTo(map);

    map.fitBounds(boundaryLayer.getBounds(), { padding: [12,12] });

    const districtNames = districts.features.map(f => f.properties.district).sort((a,b) => a.localeCompare(b,'uz'));
    districtNames.forEach(name => {
      const o = document.createElement('option');
      o.value = name;
      o.textContent = name;
      districtSelect.appendChild(o);
    });

    function styleDistrictSelection() {
      districtLayer.eachLayer(layer => {
        const name = layer.feature.properties.district;
        if (name === currentDistrict) {
          layer.setStyle({ color:'#1d4ed8', weight:3, fillOpacity:0.30 });
          layer.bringToFront();
        } else {
          districtLayer.resetStyle(layer);
        }
      });
      boundaryLayer.bringToFront();
      if (filteredMahallas) filteredMahallas.bringToFront();
    }

    function renderMahallas(filterFn = null) {
      if (filteredMahallas) map.removeLayer(filteredMahallas);
      const data = {
        type: 'FeatureCollection',
        features: mahallas.features.filter(f => !filterFn || filterFn(f))
      };
      filteredMahallas = L.geoJSON(data, {
        style: mahallaFeatureStyle,
        onEachFeature: (feature, layer) => {
          const p = feature.properties;
          layer.bindPopup(`${p.mahalla_no}
Tuman: ${p.district}
ID: ${p.mahalla_id}`);
          layer.on('click', () => focusMahallaLayer(layer, feature));
        }
      }).addTo(map);
      if (data.features.length === 0) {
        setInfo('Qidiruv natijasi topilmadi');
      }
      styleDistrictSelection();
    }

    function focusDistrict(name) {
      currentDistrict = name;
      districtSelect.value = name;
      selectedMahallaLayer = null;
      renderMahallas(f => f.properties.district === name && matchesSearch(f));
      const chosen = districts.features.find(f => f.properties.district === name);
      if (chosen) {
        const layer = districtLayer.getLayers().find(l => l.feature.properties.district === name);
        if (layer) map.fitBounds(layer.getBounds(), { padding: [20,20] });
      }
      const count = mahallas.features.filter(f => f.properties.district === name).length;
      setInfo(`
${name}
MFY soni: ${count}
Mahallani bossangiz batafsil ma’lumot chiqadi.`);
      styleDistrictSelection();
    }

    function focusMahallaLayer(layer, feature) {
      if (selectedMahallaLayer) {
        selectedMahallaLayer.setStyle(mahallaFeatureStyle(selectedMahallaLayer.feature));
      }
      selectedMahallaLayer = layer;
      layer.setStyle({ color:'#15803d', weight:2.5, fillOpacity:0.38 });
      layer.bringToFront();
      const p = feature.properties;
      setInfo(`
${p.mahalla_no}
Tuman: ${p.district}
ID: ${p.mahalla_id}`);
      map.fitBounds(layer.getBounds(), { padding: [24,24] });
      layer.openPopup();
    }

    function matchesSearch(feature) {
      const q = searchInput.value.trim().toLowerCase();
      if (!q) return true;
      return String(feature.properties.mahalla_no || '').toLowerCase().includes(q);
    }

    function applySearch() {
      const q = searchInput.value.trim().toLowerCase();
      if (!q) {
        if (currentDistrict) focusDistrict(currentDistrict);
        else resetAll();
        return;
      }
      renderMahallas(f => (!currentDistrict || f.properties.district === currentDistrict) && matchesSearch(f));
      const first = mahallas.features.find(f => (!currentDistrict || f.properties.district === currentDistrict) && matchesSearch(f));
      if (first) {
        const layer = filteredMahallas.getLayers().find(l => String(l.feature.properties.mahalla_id) === String(first.properties.mahalla_id));
        if (layer) focusMahallaLayer(layer, first);
      } else {
        setInfo('Qidiruv natijasi topilmadi');
      }
    }

    districtSelect.addEventListener('change', e => {
      if (e.target.value) focusDistrict(e.target.value);
      else resetAll();
    });

    searchInput.addEventListener('input', applySearch);

    resetBtn.addEventListener('click', resetAll);

    satBtn.addEventListener('click', () => {
      if (map.hasLayer(streets)) map.removeLayer(streets);
      if (map.hasLayer(light)) map.removeLayer(light);
      if (!map.hasLayer(satellite)) satellite.addTo(map);
    });

    function resetAll() {
      currentDistrict = '';
      districtSelect.value = '';
      searchInput.value = '';
      selectedMahallaLayer = null;
      if (filteredMahallas) map.removeLayer(filteredMahallas);
      allMahallaLayer.addTo(map);
      filteredMahallas = allMahallaLayer;
      districtLayer.eachLayer(layer => districtLayer.resetStyle(layer));
      map.fitBounds(boundaryLayer.getBounds(), { padding: [12,12] });
      setInfo('
Xaritadagi hududni bossangiz ma’lumot chiqadi.');
      boundaryLayer.bringToFront();
    }

    resetAll();
